esp_err_t garage_ui_bg_draw_background(esp_lcd_panel_handle_t panel)
{
    if (!panel) return ESP_ERR_INVALID_ARG;
    const int lines_per_flush = 8;
    uint16_t *buf = heap_caps_malloc(GARAGE_UI_BG_W * lines_per_flush * sizeof(uint16_t), MALLOC_CAP_DMA);
    if (!buf) {
        ESP_LOGE(TAG_BG, "No DMA RAM for background draw buffer");
        return ESP_ERR_NO_MEM;
    }
    for (int y = 0; y < GARAGE_UI_BG_H; y += lines_per_flush) {
        int n = GARAGE_UI_BG_H - y;
        if (n > lines_per_flush) n = lines_per_flush;
        memcpy(buf, &garage_ui_bg_rgb565_swapped[y * GARAGE_UI_BG_W], GARAGE_UI_BG_W * n * sizeof(uint16_t));
        esp_err_t err = esp_lcd_panel_draw_bitmap(panel, 0, y, GARAGE_UI_BG_W, y + n, buf);
        if (err != ESP_OK) {
            free(buf);
            return err;
        }
    }
    free(buf);
    return ESP_OK;
}

